// region Document union

/** Any content in a fired `:json` artifact, told apart by `type`. */
@Serializable(with = DocumentSerializer::class)
public sealed interface Document {
    /** A content type this build does not know — one added after it was generated. */
    public data class Unknown(public val type: String, public val raw: JsonObject) : Document
}

/** Reads a [Document] by its `type`; JSON only. */
public object DocumentSerializer : KSerializer<Document> {
    override val descriptor: SerialDescriptor = buildClassSerialDescriptor("Document")

    override fun deserialize(decoder: Decoder): Document {
        val input = decoder as? JsonDecoder ?: throw SerializationException("Document decodes from JSON only")
        val raw = input.decodeJsonElement().jsonObject
        return when (val type = (raw["type"] as? JsonPrimitive)?.contentOrNull) {
            "page" -> input.json.decodeFromJsonElement(PageDocument.serializer(), raw)
            "post" -> input.json.decodeFromJsonElement(PostDocument.serializer(), raw)
            else -> Document.Unknown(type.orEmpty(), raw)
        }
    }

    override fun serialize(encoder: Encoder, value: Document) {
        val output = encoder as? JsonEncoder ?: throw SerializationException("Document encodes to JSON only")
        val raw = when (value) {
            is PageDocument -> output.json.encodeToJsonElement(PageDocument.serializer(), value).tagged("type", "page")
            is PostDocument -> output.json.encodeToJsonElement(PostDocument.serializer(), value).tagged("type", "post")
            is Document.Unknown -> value.raw
        }
        output.encodeJsonElement(raw)
    }
}

// endregion

// region Json

/**
 * The [Json] these models expect. `ignoreUnknownKeys`, because a delivery
 * gains keys (a new custom field, a new block attribute) before the app is
 * regenerated.
 */
public val KilnJson: Json = Json { ignoreUnknownKeys = true }

// A member always carries its tag, even one built with the tag left `null`.
private fun JsonElement.tagged(key: String, tag: String): JsonObject =
    JsonObject(jsonObject + (key to JsonPrimitive(tag)))

// endregion
